using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // ─── Stock Level Tests ───────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-SKU"));
    }

    [TestMethod]
    public void AddStock_NewSku_SetsStockLevel()
    {
        _tracker.AddStock("SKU-001", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-001", 30);
        _tracker.AddStock("SKU-001", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NegativeQuantity_Throws()
    {
        _tracker.AddStock("SKU-001", -5);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_ZeroQuantity_Throws()
    {
        _tracker.AddStock("SKU-001", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void AddStock_NullSku_Throws()
    {
        _tracker.AddStock(null!, 10);
    }

    // ─── Reorder Alert Tests ─────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-001", 5);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-001", 100);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("UNKNOWN-SKU"));
    }

    // ─── Warehouse Transfer Tests ────────────────────────────────────

    [TestMethod]
    public void Transfer_MovesStockBetweenSkus()
    {
        _tracker.AddStock("WH-A", 100);
        _tracker.AddStock("WH-B", 20);

        _tracker.Transfer("WH-A", "WH-B", 30);

        Assert.AreEqual(70, _tracker.GetStockLevel("WH-A"));
        Assert.AreEqual(50, _tracker.GetStockLevel("WH-B"));
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void Transfer_InsufficientStock_Throws()
    {
        _tracker.AddStock("WH-A", 10);

        _tracker.Transfer("WH-A", "WH-B", 50);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void Transfer_ZeroQuantity_Throws()
    {
        _tracker.AddStock("WH-A", 10);

        _tracker.Transfer("WH-A", "WH-B", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void Transfer_SameSourceAndDestination_Throws()
    {
        _tracker.AddStock("WH-A", 50);

        _tracker.Transfer("WH-A", "WH-A", 10);
    }
}

